"""Construct a conservative revision of first_edit.tex. No optimisation is executed."""
from pathlib import Path
import shutil,re,csv,json,difflib,html,hashlib
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[1]
SOURCE=ROOT/'paper/first_edit.tex'
OLD=ROOT/'paper/final_submission'
original=SOURCE.read_text(encoding='utf-8')
s=original
changes=[]
def replace(old,new,reason):
    global s
    if old not in s: raise ValueError('Missing replacement: '+old[:120])
    s=s.replace(old,new)
    changes.append({'reason':reason,'old':old,'new':new})
def span(start,end,new,reason):
    global s
    a=s.index(start); b=s.index(end,a)
    replace(s[a:b],new+'\n\n',reason)
def paragraph(start,new,reason):
    a=s.index(start); b=s.find('\n\n',a)
    replace(s[a:b],new,reason)
for folder in ('images','data','tables','supplement','review','build'):
    (HERE/folder).mkdir(exist_ok=True)
for p in (ROOT/'paper/images').glob('*'):
    if p.is_file():shutil.copy2(p,HERE/'images'/p.name)
for folder in ('data','tables'):
    shutil.copytree(OLD/folder,HERE/folder,dirs_exist_ok=True)
shutil.copy2(OLD/'references.bib',HERE/'references.bib')
bib=(HERE/'references.bib').read_text(encoding='utf-8')
bib=re.sub(r'(?m)(=\s*\{[^\n]*\})(\n\s*\w+\s*=)',r'\1,\2',bib)
(HERE/'references.bib').write_text(bib,encoding='utf-8')
