# Replace individual labelled equations, preserving their labels and all conceptual constraints.
def equation(label,text):
    global s
    lines=s.splitlines(); idx=next(i for i,l in enumerate(lines) if r'\label{'+label+'}' in l)
    start=idx
    while start>0 and (r'\nonumber' in lines[start-1] or r'\notag' in lines[start-1]):start-=1
    replace('\n'.join(lines[start:idx+1]),text,'Update implemented constraint '+label+'.')
equation('eq:util_bounds',r'& 0\leq u(t,k,s)\leq u_{\max},\quad (t,k)\in\mathcal A_d,\ s\in W_{t,k} \label{eq:util_bounds} \\')
equation('eq:power_base',r'& P^{\mathrm{IT}}_{\mathrm{base}}(s)=\widehat f\bigl(u^{\mathrm{inflex}}(s)+u^{\mathrm{flex,base}}(s)\bigr) \label{eq:power_base} \\')
equation('eq:feasibility',r'& u(t,k,s)=0\quad\text{if }s<t\text{ or }s>t+D_k,\quad (t,k)\in\mathcal A_d \label{eq:feasibility} \\')
equation('eq:alpha_sum',r'& \sum_{k\in K}\alpha_{t,k}=1\quad\text{for each new arrival }t \label{eq:alpha_sum} \\')
equation('eq:job_completion',r'''& \sum_{s\in W_{t,k}}u(t,k,s)\Delta t
\begin{cases}=A_{t,k,d},&t+D_k\leq L_d,\\ \leq A_{t,k,d},&t+D_k>L_d,\end{cases} \label{eq:job_completion} \\''')
equation('eq:cpu_capacity_new',r'& u^{\mathrm{inflex}}(s)+\sum_{(t,k)\in\mathcal A_d:\,s\in W_{t,k}}u(t,k,s)\leq u_{\max},\quad s\in T^{\mathrm{ext}}. \label{eq:cpu_capacity_new}')

